/**
 *
 * Rating is a component that displays a rating value.
 *
 * [Live Demo](https://www.primereact.org/rating/)
 *
 * @module RatingRoot
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { UseRatingExposes, UseRatingProps, UseRatingState, UseRatingValueChangeEvent } from '@primereact/types/headless/rating';
/**
 * Event fired when the Rating component value changes.
 */
export interface RatingRootValueChangeEvent extends UseRatingValueChangeEvent<React.SyntheticEvent> {
}
/**
 * Defines passthrough(pt) options type in Rating component.
 */
export type RatingRootPassThroughType<E> = PassThroughType<RatingRootInstance, E>;
/**
 * Defines passthrough(pt) options of Rating component.
 */
export interface RatingRootPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: RatingRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to each option element.
     */
    option?: RatingRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the on-icon (filled) overlay element.
     */
    onIcon?: RatingRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the off-icon (empty) base element.
     */
    offIcon?: RatingRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the half-value sr-only radio input.
     */
    halfInput?: RatingRootPassThroughType<React.InputHTMLAttributes<HTMLInputElement>>;
    /**
     * Used to pass attributes to the full-value sr-only radio input.
     */
    fullInput?: RatingRootPassThroughType<React.InputHTMLAttributes<HTMLInputElement>>;
}
/**
 * Defines valid properties in Rating component.
 */
export interface RatingRootProps extends BaseComponentProps<RatingRootInstance, UseRatingProps, RatingRootPassThrough> {
}
/**
 * Defines valid state in Rating component.
 */
export interface RatingRootState extends UseRatingState {
}
/**
 * Defines the methods and properties exposed by Rating component.
 */
export interface RatingRootExposes extends UseRatingExposes {
}
/**
 * Instance of Rating component.
 */
export type RatingRootInstance = ComponentInstance<RatingRootProps, RatingRootState, RatingRootExposes>;
